# over refund
p=mk()
try: outage_refund(p,Decimal("80.01"),T0)
except BillingError as e: print("over:",e.code)
# non positive
for a in [Decimal("0"),Decimal("-1")]:
    try: outage_refund(mk(),a,T0)
    except BillingError as e: print("nonpos:",e.code)
# not captured
try: outage_refund(mk("authorized"),Decimal("1"),T0)
except BillingError as e: print("state:",e.code)
# returns payment
p=mk(); assert outage_refund(p,Decimal("1"),T0) is p
print("all edge cases ok")
